<?php
 namespace App\Providers; use Iidestiny\Flysystem\Oss\OssAdapter; use Illuminate\Filesystem\FilesystemAdapter; use Illuminate\Support\ServiceProvider; use League\Flysystem\Filesystem; class OssServiceProvider extends ServiceProvider { public function boot() { $this->app['filesystem']->extend('oss', function ($app, $config) { $scheme = !empty($config['ssl']) ? 'https://' : 'http://'; $endpoint = $config['endpoint']; if (!str_contains($endpoint, '://')) { $endpoint = $scheme . $endpoint; } $adapter = new OssAdapter($config['access_id'], $config['access_key'], $endpoint, $config['bucket'], (bool) ($config['isCName'] ?? false), $config['root'] ?? ''); if (!empty($config['cdnDomain'])) { $cdn = $config['cdnDomain']; $adapter->setCdnUrl(str_contains($cdn, '://') ? $cdn : $scheme . $cdn); } return new FilesystemAdapter(new Filesystem($adapter), $adapter, $config); }); } } 